	local okFetch, response = pcall(function()
		return game:HttpGet(UI_URL)
	end)
	if not okFetch or type(response) ~= "string" or #response < 50 then
		warn("[Lynx] UI library download failed:", response)
		error("[Lynx] HttpGet failed for MainLib vd.lua")
	end
	local okCompile, compiled = pcall(loadstring, response)
	if not okCompile or type(compiled) ~= "function" then
		warn("[Lynx] UI compile failed:", compiled)
		error("[Lynx] loadstring failed for MainLib vd.lua")
	end
	local okRun, result = pcall(compiled)
	if not okRun or type(result) ~= "table" then
		warn("[Lynx] UI runtime failed:", result)
		error("[Lynx] library init failed: " .. tostring(result))
	end
	lib = result
	print("[Lynx] UI library loaded")
end
